  "Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.": "Samsoom знает наш каталог, классы, часы работы и доставку. Он находит деталь, объясняет класс и передаёт вас живому человеку в WhatsApp, как только нужно.",
