  "Original or Service Pack for the best result, OLED for value, Incell when budget comes first.": "Original или Service Pack — для лучшего результата, OLED — выгодно, Incell — когда важен бюджет.",
  "Original or Service Pack for the best result. OLED is great value. Incell when budget comes first. Every grade is labelled on your order.": "Original или Service Pack — для лучшего результата. OLED — отличная цена. Incell — когда важен бюджет. Класс указан в каждом заказе.",
  "Yes. We ship every day to the Middle East, Africa, Europe and Asia. Tracked, packed by hand, quoted with your order.": "Да. Отправляем каждый день на Ближний Восток, в Африку, Европу и Азию. С отслеживанием, ручной упаковкой и расчётом с заказом.",
  "Yes. We ship worldwide, mainly to the Middle East, Africa, Europe and Asia. Tracked and securely packed; shipping is quoted with your order.": "Да. Доставляем по всему миру, в основном на Ближний Восток, в Африку, Европу и Азию. С отслеживанием и надёжной упаковкой; доставка рассчитывается с заказом.",
  "Our bench in Deira fixes screens, batteries, charging ports and board faults. Try the estimator for a price range.": "Наш верстак в Дейре чинит экраны, батареи, разъёмы зарядки и платы. Попробуйте калькулятор, чтобы узнать диапазон цен.",
  "I didn’t catch that one. Try a model and part, like “A54 battery” or “iPhone 13 screen”, or ask about grades, hours or shipping.": "Не понял. Укажите модель и деталь, например «батарея A54» или «экран iPhone 13», или спросите про классы, часы или доставку.",
