  "Only account holders can rate parts, and reviews of parts you bought are marked \"verified purchase\". Reviews must be honest and about the part. We remove reviews that are abusive, off-topic, contain personal data or advertise other businesses.": "Оценивать детали могут только владельцы аккаунтов, а отзывы о купленных деталях помечаются «подтверждённая покупка». Отзывы должны быть честными и о детали. Мы удаляем оскорбительные, не относящиеся к делу, содержащие персональные данные или рекламу отзывы.",
  "Only account holders can rate parts, so every review is from a real customer.": "Оценивать могут только владельцы аккаунтов, поэтому каждый отзыв — от настоящего клиента.",
  "Open application": "Свободная заявка",
