  "Orders, stars, points, companies and your chats with Samsoom, all in one place.": "Заказы, звёзды, баллы, компании и чаты с Samsoom — всё в одном месте.",
  "Original (Service Pack) is the part the brand fits. OLED Soft is close to original at a lower price. Incell is a reliable budget LCD. AAA is our best-price grade. Every part is labelled by quality and manufacturer.": "Original (Service Pack) — деталь, которую ставит сам бренд. OLED Soft близок к оригиналу и дешевле. Incell — надёжный бюджетный LCD. AAA — наш самый выгодный класс. На каждой детали указаны качество и производитель.",
  "Original (Service Pack): 6 months. OLED Soft: 3 months. Incell and AAA: 1 month. Other parts: as stated on the product. The warranty starts on the invoice date.": "Original (Service Pack): 6 месяцев. OLED Soft: 3 месяца. Incell и AAA: 1 месяц. Остальные детали — как указано в карточке. Гарантия начинается с даты счёта.",
  "Original / Compatible · up to 6 months": "Оригинал / Совместимая · до 6 месяцев",
  "Original grade · 3 months": "Оригинальный класс · 3 месяца",
  "Original parts in the brand’s service packaging, the same ones authorised service centres fit. Exact colors, brightness, touch and battery life.": "Оригинальные детали в сервисной упаковке бренда — те же, что ставят авторизованные центры. Точные цвета, яркость, сенсор и автономность.",
  "Original parts recovered and rebuilt (for example a new glass on an original panel), then tested.": "Оригинальные детали, восстановленные (например, новое стекло на оригинальной панели) и проверенные.",
  "Original · 6 months": "Оригинал · 6 месяцев",
  "Original · Service Pack": "Оригинал · Service Pack",
  "Original, OLED, Incell and AAA, side by side.": "Original, OLED, Incell и AAA — рядом.",
