  "Our management team reviews every application by hand. We reply by e-mail and WhatsApp.": "Руководство вручную рассматривает каждую заявку. Отвечаем по e-mail и в WhatsApp.",
  "Our staff, according to their role, and the service providers that run the site for us (hosting, database, e-mail, payments, shipping partners for your delivery) under contracts that protect it.": "Наши сотрудники в рамках своих ролей и подрядчики, обслуживающие сайт (хостинг, база данных, почта, платежи, партнёры по доставке), по договорам, защищающим данные.",
