  "Physical damage (cracks, bends, pressure marks), liquid damage, parts damaged while being fitted by a third party, parts with removed or altered labels, and normal wear such as battery capacity loss within specification.": "Физические повреждения (трещины, изгибы, следы давления), попадание жидкости, детали, повреждённые при установке третьими лицами, детали со снятыми или изменёнными этикетками и обычный износ, например снижение ёмкости батареи в пределах нормы.",
