  "The brand’s own part": "Деталь самого бренда",
  "The card for everyone who buys parts or repairs with us. Register online, your first purchase activates it, and every dirham you spend charges it up.": "Карта для всех, кто покупает детали или ремонтирует у нас. Зарегистрируйтесь онлайн, первая покупка активирует её, а каждый потраченный дирхам заряжает.",
  "The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.": "Оплата зависит от цены детали. Мастер может скорректировать её с учётом детали и работы и всегда предупреждает до начала.",
  "The fine print,": "Мелкий шрифт —",
  "The part and the fitting fee both count.": "Учитываются и деталь, и установка.",
  "The part the brand itself fits, in its service box. Same colors, brightness, touch and battery life as new. Our longest warranty.": "Деталь, которую ставит сам бренд, в сервисной коробке. Те же цвета, яркость, сенсор и автономность, что у нового. Наша самая длинная гарантия.",
  "The part the brand itself fits.": "Деталь, которую ставит сам бренд.",
  "The people behind the counter.": "Люди за прилавком.",
  "The phones we stock parts for, and the factories behind every part, so you always know exactly what you are buying.": "Телефоны, для которых у нас есть детали, и фабрики за каждой деталью — чтобы вы всегда знали, что покупаете.",
  "The whole shop": "Весь магазин",
  "These terms are governed by the laws of the Emirate of Dubai and the federal laws of the UAE. The courts of Dubai have jurisdiction.": "Эти условия регулируются законами эмирата Дубай и федеральными законами ОАЭ. Споры рассматривают суды Дубая.",
  "This site keeps a few things in your browser so it works: your language, your cart, stars and recent searches, whether you have seen Samsoom’s tour, and your sign-in session. We do not use advertising cookies.": "Сайт хранит в браузере немного данных для работы: язык, корзину, звёзды и недавние запросы, видели ли вы экскурсию Samsoom, и сессию входа. Рекламные cookie мы не используем.",
  "Three steps to trade prices.": "Три шага к оптовым ценам.",
  "Tip: create your account first so the approval is linked to it.": "Совет: сначала создайте аккаунт, чтобы одобрение было привязано к нему.",
  "Title": "Заголовок",
  "To be the parts counter repair shops trust most, from Dubai to Madrid and beyond.": "Быть прилавком деталей, которому мастерские доверяют больше всего, от Дубая до Мадрида и дальше.",
  "To sell and deliver parts, run repairs and warranties, approve trade accounts, answer you, keep the accounts required by UAE tax law, and improve the site. We do not sell your data.": "Чтобы продавать и доставлять детали, выполнять ремонт и гарантию, одобрять оптовые аккаунты, отвечать вам, вести учёт по налоговому закону ОАЭ и улучшать сайт. Мы не продаём ваши данные.",
  "Too short": "Слишком короткий",
