  "Up to 15% off.": "Скидка до 15%.",
  "Up to 6 months": "До 6 месяцев",
  "Up to 6 months on Original, 3 months on OLED, 1 month on Incell and AAA. It covers faults of the part itself.": "До 6 месяцев на Original, 3 — на OLED, 1 месяц — на Incell и AAA. Покрывает неисправности самой детали.",
  "Up to 6 months, by grade.": "До 6 месяцев, в зависимости от класса.",
  "Use “Forgot your password?” on the sign-in page and we e-mail you a reset link.": "Нажмите «Забыли пароль?» на странице входа — пришлём ссылку для сброса.",
  "Usually within one working day.": "Обычно в течение рабочего дня.",
