  "WHERE WE SHIP": "КУДА МЫ ДОСТАВЛЯЕМ",
  "WHO IT IS FOR": "ДЛЯ КОГО",
  "WHO WE ARE": "КТО МЫ",
  "WHOLESALE · TRADE ACCOUNTS": "ОПТ · ТОРГОВЫЕ АККАУНТЫ",
  "WORLDWIDE SHIPPING": "ДОСТАВКА ПО МИРУ",
  "WRITE TO US": "НАПИШИТЕ НАМ",
  "Waiting for review": "Ожидает проверки",
  "Walk in any time we are open, or book a time and skip the queue. We confirm on WhatsApp.": "Приходите в часы работы или запишитесь и пропустите очередь. Подтвердим в WhatsApp.",
  "Warranty & quality": "Гарантия и качество",
  "Warranty & returns": "Гарантия и возврат",
  "Warranty covers faults from the part itself. It does not cover physical or water damage, or parts fitted elsewhere that were damaged while fitting.": "Гарантия покрывает неисправности самой детали. Не покрывает физические повреждения, воду и детали, повреждённые при установке в другом месте.",
  "Warranty or return": "Гарантия или возврат",
  "Warranty policy": "Гарантийная политика",
  "We accept cash and card in the shop, bank transfer, and payment links we send after confirming your order. Orders are released for delivery or collection once paid, unless your trade account has approved credit.": "Принимаем наличные и карты в магазине, перевод и ссылки на оплату после подтверждения заказа. Заказы выдаются после оплаты, если у оптового аккаунта нет одобренного кредита.",
  "We book the best route for your parcel: express for urgent parts, air cargo for bulk.": "Выбираем лучший маршрут: экспресс для срочного, авиагруз для объёма.",
  "We check the phone in front of you.": "Проверяем телефон при вас.",
  "We confirm on WhatsApp, then send a payment link": "Подтвердим в WhatsApp и пришлём ссылку на оплату",
  "We help with packing and paperwork, but the shipping cost and the shipper’s terms are between you and your shipper.": "Помогаем с упаковкой и документами, но стоимость и условия доставки — между вами и вашим перевозчиком.",
  "We hire people who like phones, people and getting things exactly right. Openings are samples until the owner publishes real ones.": "Мы нанимаем тех, кто любит телефоны, людей и точность. Вакансии — примеры, пока владелец не опубликует настоящие.",
  "We opened WhatsApp with your booking; the team confirms the time there.": "Мы открыли WhatsApp с вашей записью; команда подтвердит время там.",
  "We opened WhatsApp with your request; the team replies there.": "Мы открыли WhatsApp с вашим запросом; команда ответит там.",
  "We quote shipping": "Считаем доставку",
  "We received your application and will be in touch.": "Мы получили заявку и свяжемся с вами.",
  "We received your order. Our team confirms stock, delivery and the final price on WhatsApp, usually within minutes during opening hours.": "Мы получили заказ. Команда подтвердит наличие, доставку и итоговую цену в WhatsApp, обычно за несколько минут в часы работы.",
  "We reply here during opening hours, and by e-mail after.": "Отвечаем здесь в часы работы, а позже — по e-mail.",
  "We sent a 6-digit code to": "Мы отправили 6-значный код на",
  "We ship door to door with our partners (such as Sky Dragon, Emirates SkyCargo, UPS and DHL) and quote the price and time before you pay. Duties and taxes in the destination country are paid by the receiver unless agreed otherwise.": "Доставляем от двери до двери с партнёрами (Sky Dragon, Emirates SkyCargo, UPS, DHL) и называем цену и срок до оплаты. Пошлины и налоги в стране назначения платит получатель, если не договорились иначе.",
  "We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.": "Каждую неделю отправляем детали мастерским и торговцам Ближнего Востока, Африки, Европы и Азии: от двери до двери с партнёрами или с вашим перевозчиком.",
  "We ship to 28+ countries every week, door to door, and we can hand your order to your own shipper.": "Каждую неделю доставляем в 28+ стран от двери до двери и можем передать заказ вашему перевозчику.",
  "We started in 2003 as Syria Tell. In 2020 the shop took the name Sam Electronics, with the same management and the same people behind the counter.": "Мы начали в 2003 году как Syria Tell. В 2020-м магазин стал называться Sam Electronics — с тем же руководством и теми же людьми за прилавком.",
  "We verify and approve": "Проверяем и одобряем",
  "We will confirm it is you by e-mail, then act on it.": "Подтвердим вашу личность по e-mail и выполним запрос.",
