  "Yes. A repair shop owner can hold a Sam Grid card for the business and a Sam Circuit card for personal purchases. Both show in My Bench.": "Да. Владелец мастерской может иметь Sam Grid для бизнеса и Sam Circuit для личных покупок. Обе видны в My Bench.",
