  "your trade card": "ваша торговая карта",
  "AED 1 = 1 point, on every part and every repair.": "1 AED = 1 балл за каждую деталь и каждый ремонт.",
  "AED 1 = 1 point on every part and repair. Your level rises as your points do.": "1 AED = 1 балл за каждую деталь и ремонт. Уровень растёт вместе с баллами.",
  "The trade card. Apply online with your trade licence; our management team checks it and activates the card by hand. Your monthly volume sets your level.": "Торговая карта. Подайте заявку онлайн с торговой лицензией; руководство проверит её и активирует карту вручную. Ваш месячный объём определяет уровень.",
  "estimate": "оценка",
  "Newest": "Новые",
  "Everything": "Всё",
  "Yes: the part and the fitting fee both count, AED 1 = 1 point.": "Да: учитываются и деталь, и установка, 1 AED = 1 балл.",
  "From your approved trade orders in the last 30 days. It is reviewed every month; you never drop more than one level at a time.": "По одобренным оптовым заказам за последние 30 дней. Пересматривается ежемесячно; за раз можно опуститься не больше чем на один уровень.",
  "Send a list on WhatsApp or upload it; we price it the same day.": "Пришлите список в WhatsApp или загрузите его — оценим в тот же день.",
  "Retailer": "Розничный продавец",
