  "Plaza Mayor district, Madrid, Spain": "Район Пласа-Майор, Мадрид, Испания",
  "Sales": "Продажи",
  "Knows grades and manufacturers by heart; advises trade customers at the counter and on WhatsApp.": "Знает классы и производителей наизусть; консультирует оптовиков у прилавка и в WhatsApp.",
  "Operations": "Операции",
  "Checks, packs and ships parts worldwide; keeps the stock exact.": "Проверяет, упаковывает и отправляет детали по миру; держит учёт точным.",
  "Complaint": "Жалоба",
  "Partnership": "Партнёрство",
  "Prices in the shop are shown without VAT; 5% UAE VAT is added at checkout and shown on your invoice.": "Цены в магазине указаны без НДС; НДС ОАЭ 5% добавляется при оформлении и указывается в счёте.",
  "Bring or send it back with the invoice within the warranty. We test it; if it is faulty we replace it or refund you. See the returns policy for the details.": "Принесите или пришлите её с чеком в пределах гарантии. Мы проверим; если неисправна — заменим или вернём деньги. Подробнее в политике возврата.",
  "Cookies": "Cookie",
  "These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates (\"Sam Electronics\", \"we\"), in the shop, on this website, on WhatsApp or by phone.": "Эти условия применяются ко всем продажам Sam Electronics L.L.C, Аль-Мурар, Дейра, Дубай, ОАЭ («Sam Electronics», «мы») в магазине, на сайте, в WhatsApp или по телефону.",
  "Prices": "Цены",
  "Prices are in UAE dirhams (AED). Prices shown in the shop do not include VAT; 5% UAE VAT is added at checkout and shown on the tax invoice.": "Цены в дирхамах ОАЭ (AED). Цены в магазине без НДС; 5% добавляются при оформлении и указываются в налоговом счёте.",
  "Orders": "Заказы",
  "Liability": "Ответственность",
  "Refunds": "Возврат средств",
  "You may ask us to hand your order to your own shipper or cargo agent. We pack it and share the paperwork; the shipping cost and the shipper’s terms are between you and your shipper, and responsibility passes to you when we hand the parcel over.": "Вы можете попросить передать заказ вашему перевозчику или карго-агенту. Мы упакуем и передадим документы; стоимость и условия доставки — между вами и перевозчиком, ответственность переходит к вам при передаче посылки.",
  "You can clear them at any time in your browser; the site will simply forget your cart and preferences on that device.": "Их можно удалить в браузере в любой момент; сайт просто забудет корзину и настройки на этом устройстве.",
  "A well-known aftermarket maker with consistent quality and packaging; our usual AAA choice.": "Известный производитель неоригинальных деталей со стабильным качеством и упаковкой; наш обычный выбор для AAA.",
