  "No model matches. Try the full Find My Part.": "Модель не найдена. Попробуйте полный Find My Part.",
  "Search results": "Результаты поиска",
  "See it all": "Смотреть всё",
  "All models": "Все модели",
  "Parts for this model are on request. Ask us on WhatsApp.": "Детали для этой модели под заказ. Спросите нас в WhatsApp.",
  "About {x}": "О {x}",
  "+{n} in the last hour": "+{n} за последний час",
