  'Tell me a joke': 'Расскажи шутку',
  'iPhone 13 screen fitted': 'Экран iPhone 13 с установкой',
  'iPhone 13 screen repair price': 'Цена ремонта экрана iPhone 13',
  'I read your photo: it is a': 'Я прочитал ваше фото: это',
  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'На фото виден номер IMEI. Отправьте его команде в WhatsApp, и они найдут точную модель.',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'Я присмотрелся, но не нашёл модель на этом фото. Лучше всего скриншот «Настройки → О телефоне», или просто назовите модель.',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'Я умею читать текст на фото, но здесь модель не нашёл. Попробуйте наклейку на коробке или напишите модель, дальше я сам.',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'Пришлите фото кнопкой камеры: лучше всего скриншот «Настройки → О телефоне» или наклейка на коробке. Я прочитаю модель.',
  'Settings → About phone → Model.': 'Настройки → О телефоне → Модель.',
  'Settings → About phone → All specs → Model.': 'Настройки → О телефоне → Все характеристики → Модель.',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'Наберите *#06#, чтобы узнать IMEI, и пришлите нам: найдём точную модель.',
  'Still about your': 'Всё ещё о вашем',
  'Tell me the part: screen, battery, camera or charging port.': 'Назовите деталь: экран, аккумулятор, камера или разъём зарядки.',
  'Sure, for which model?': 'Конечно, для какой модели?',
  'Tell me the model and I’ll find it.': 'Назовите модель, и я найду.',
  'Which one are you after?': 'Что именно ищете?',
  'good news, we have these': 'хорошие новости, есть вот что',
  'this is on our shelf': 'вот что есть у нас на полке',
  'Tap + to add one to your cart.': 'Нажмите +, чтобы добавить в корзину.',
  'Want it fitted? Ask me for the repair price.': 'Нужна установка? Спросите цену ремонта.',
  'We’re in Al Murar, Deira, Dubai.': 'Мы в Аль-Мурар, Дейра, Дубай.',
  'Tap below for the map and directions.': 'Нажмите ниже, чтобы открыть карту и маршрут.',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'Позвоните в магазин, напишите нам в WhatsApp или WeChat, или на e-mail. Мы @samelectronics.uae в Instagram, TikTok и Facebook.',
  'Every part has a warranty that depends on the grade:': 'На каждую деталь есть гарантия, срок зависит от класса:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'Назовите модель и деталь, например «аккумулятор A54» или «экран iPhone 13», и я покажу цену каждого класса.',
  'The dirham is pegged to the dollar, so this rate stays the same.': 'Дирхам привязан к доллару, так что курс не меняется.',
