  'Pictures may load slower.': 'Картинки могут грузиться дольше.',
  'Our Deira store in Dubai is open now. Allo Madrid opens soon, and I can let you know the day it does.': 'Наш магазин в Дейре, Дубай, уже открыт. Allo Madrid скоро откроется — я сообщу в день открытия.',
  'Brand, model, part: every grade in seconds.': 'Бренд, модель, деталь: все качества за секунды.',
