  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'Реклама магазина: экраны, любое качество, неделя аккумуляторов, оптовые цены, доставка по миру.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'Большой блок показывает наши свежие предложения. Выберите вкладку, деталь или бренд — и увидите скидки именно по ним.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'Цветная метка — качество (Original, OLED, Incell, AAA и др.). Тёмная со светодиодом — производитель.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Отметьте звёздочкой, чтобы сохранить в My Bench. Кнопка с двумя карточками добавит к сравнению: до трёх деталей рядом.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Сортируйте по цене, новизне или соответствию и переключайте сетку и список.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Мастерские и торговцы: подайте заявку один раз — и у каждой детали будет ваша оптовая цена.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'Самые частые вопросы в одном месте. Остались вопросы? Спросите Samsoom.',
