  'I can watch that for you. Find the part below and I will ring the bell when it is back.': 'Я послежу. Найдите деталь ниже — позвоню в колокольчик, когда появится.',
  'I can watch the price for you. Find the part below.': 'Послежу за ценой. Найдите деталь ниже.',
  'Let us check what fits. Tell me your phone below.': 'Проверим совместимость. Укажите телефон ниже.',
